use anyhow::Result;
use clap::Parser;
use rustpython_parser::{parse, Mode};
use std::fs;
use std::path::PathBuf;

#[derive(Parser)]
#[command(author, version, about = "A quick Python parser in Rust")]
struct Cli {
    /// Python source file to parse
    #[arg(short, long)]
    file: Option<BufBuf>,

    /// Python source string to parse
    #[arg(short, long)]
    source: Option<String>,
}

type BufBuf = PathBuf; // workaround for PathBuf being used in #[arg]

fn main() -> Result<()> {
    let cli = Cli::parse();

    let (content, filename) = if let Some(path) = cli.file {
        (fs::read_to_string(&path)?, path.to_string_lossy().into_owned())
    } else if let Some(src) = cli.source {
        (src, "<string>".to_string())
    } else {
        // Default example
        (
            "def hello_world():\n    print('Hello, toolpath!')".to_string(),
            "<embedded>".to_string(),
        )
    };

    let mode = Mode::Module;

    match parse(&content, mode, &filename) {
        Ok(ast) => println!("Parsed AST:\n{:#?}", ast),
        Err(err) => eprintln!("Failed to parse Python code: {:?}", err),
    }

    Ok(())
}

