+use std::cell::RefCell;
+use std::collections::HashMap;
+use std::fmt;
+use std::rc::Rc;
+
+type RuntimeResult<T> = Result<T, RuntimeError>;
+
+#[derive(Debug, Clone, PartialEq, Eq)]
+pub struct RuntimeError(pub String);
+
+impl fmt::Display for RuntimeError {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        f.write_str(&self.0)
+    }
+}
+
+impl std::error::Error for RuntimeError {}
+
+#[derive(Debug, Clone, PartialEq)]
+pub enum Value {
+    None,
+    Bool(bool),
+    Int(i64),
+    String(String),
+    Function(UserFunction),
+}
+
+impl Value {
+    fn truthy(&self) -> bool {
+        match self {
+            Value::None => false,
+            Value::Bool(value) => *value,
+            Value::Int(value) => *value != 0,
+            Value::String(value) => !value.is_empty(),
+            Value::Function(_) => true,
+        }
+    }
+
+    fn type_name(&self) -> &'static str {
+        match self {
+            Value::None => "None",
+            Value::Bool(_) => "bool",
+            Value::Int(_) => "int",
+            Value::String(_) => "str",
+            Value::Function(_) => "function",
+        }
+    }
+
+    fn render(&self) -> String {
+        match self {
+            Value::None => "None".to_string(),
+            Value::Bool(value) => {
+                if *value {
+                    "True".to_string()
+                } else {
+                    "False".to_string()
+                }
+            }
+            Value::Int(value) => value.to_string(),
+            Value::String(value) => value.clone(),
+            Value::Function(function) => format!("<function {}>", function.name),
+        }
+    }
+}
+
+#[derive(Debug, Clone, PartialEq)]
+pub struct UserFunction {
+    name: String,
+    params: Vec<String>,
+    body: Vec<Stmt>,
+    closure: ScopeRef,
+}
+
+#[derive(Debug, Clone, PartialEq)]
+pub enum Expr {
+    Value(Value),
+    Variable(String),
+    Unary {
+        op: UnaryOp,
+        expr: Box<Expr>,
+    },
+    Binary {
+        left: Box<Expr>,
+        op: BinaryOp,
+        right: Box<Expr>,
+    },
+    Call {
+        callee: Box<Expr>,
+        args: Vec<Expr>,
+    },
+}
+
+#[derive(Debug, Clone, PartialEq)]
+pub enum Stmt {
+    Assign { name: String, expr: Expr },
+    Expr(Expr),
+    FunctionDef {
+        name: String,
+        params: Vec<String>,
+        body: Vec<Stmt>,
+    },
+    If {
+        condition: Expr,
+        then_body: Vec<Stmt>,
+        else_body: Vec<Stmt>,
+    },
+    While {
+        condition: Expr,
+        body: Vec<Stmt>,
+    },
+    Return(Expr),
+}
+
+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
+pub enum UnaryOp {
+    Negate,
+    Not,
+}
+
+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
+pub enum BinaryOp {
+    Add,
+    Subtract,
+    Multiply,
+    Divide,
+    Modulo,
+    Equal,
+    NotEqual,
+    Less,
+    LessEqual,
+    Greater,
+    GreaterEqual,
+    And,
+    Or,
+}
+
+#[derive(Debug, Clone, PartialEq, Eq)]
+struct Line {
+    indent: usize,
+    content: String,
+}
+
+#[derive(Debug, Clone, PartialEq)]
+enum Token {
+    Int(i64),
+    String(String),
+    Identifier(String),
+    True,
+    False,
+    None,
+    Plus,
+    Minus,
+    Star,
+    Slash,
+    Percent,
+    LParen,
+    RParen,
+    Comma,
+    EqEq,
+    NotEq,
+    Lt,
+    LtEq,
+    Gt,
+    GtEq,
+    And,
+    Or,
+    Not,
+    Eof,
+}
+
+#[derive(Debug, Default)]
+pub struct Interpreter {
+    globals: ScopeRef,
+    output: String,
+}
+
+impl Interpreter {
+    pub fn new() -> Self {
+        Self::default()
+    }
+
+    pub fn run(&mut self, source: &str) -> RuntimeResult<String> {
+        let program = parse_program(source)?;
+        self.output.clear();
+        self.execute_block(&program, self.globals.clone())?;
+        Ok(self.output.clone())
+    }
+
+    fn execute_block(&mut self, block: &[Stmt], scope: ScopeRef) -> RuntimeResult<Option<Value>> {
+        for stmt in block {
+            if let Some(value) = self.execute_stmt(stmt, scope.clone())? {
+                return Ok(Some(value));
+            }
+        }
+        Ok(None)
+    }
+
+    fn execute_stmt(&mut self, stmt: &Stmt, scope: ScopeRef) -> RuntimeResult<Option<Value>> {
+        match stmt {
+            Stmt::Assign { name, expr } => {
+                let value = self.eval(expr, scope.clone())?;
+                scope.borrow_mut().values.insert(name.clone(), value);
+                Ok(None)
+            }
+            Stmt::Expr(expr) => {
+                self.eval(expr, scope)?;
+                Ok(None)
+            }
+            Stmt::FunctionDef { name, params, body } => {
+                let function = UserFunction {
+                    name: name.clone(),
+                    params: params.clone(),
+                    body: body.clone(),
+                    closure: scope.clone(),
+                };
+                scope
+                    .borrow_mut()
+                    .values
+                    .insert(name.clone(), Value::Function(function));
+                Ok(None)
+            }
+            Stmt::If {
+                condition,
+                then_body,
+                else_body,
+            } => {
+                let branch = if self.eval(condition, scope.clone())?.truthy() {
+                    then_body
+                } else {
+                    else_body
+                };
+                self.execute_block(branch, Scope::child(scope))
+            }
+            Stmt::While { condition, body } => {
+                while self.eval(condition, scope.clone())?.truthy() {
+                    if let Some(value) = self.execute_block(body, Scope::child(scope.clone()))? {
+                        return Ok(Some(value));
+                    }
+                }
+                Ok(None)
+            }
+            Stmt::Return(expr) => Ok(Some(self.eval(expr, scope)?)),
+        }
+    }
+
+    fn eval(&mut self, expr: &Expr, scope: ScopeRef) -> RuntimeResult<Value> {
+        match expr {
+            Expr::Value(value) => Ok(value.clone()),
+            Expr::Variable(name) => scope
+                .borrow()
+                .get(name)
+                .ok_or_else(|| RuntimeError(format!("undefined variable: {name}"))),
+            Expr::Unary { op, expr } => {
+                let value = self.eval(expr, scope)?;
+                match op {
+                    UnaryOp::Negate => match value {
+                        Value::Int(value) => Ok(Value::Int(-value)),
+                        other => Err(RuntimeError(format!(
+                            "cannot negate {}",
+                            other.type_name()
+                        ))),
+                    },
+                    UnaryOp::Not => Ok(Value::Bool(!value.truthy())),
+                }
+            }
+            Expr::Binary { left, op, right } => {
+                if *op == BinaryOp::And {
+                    let left = self.eval(left, scope.clone())?;
+                    if !left.truthy() {
+                        return Ok(left);
+                    }
+                    return self.eval(right, scope);
+                }
+                if *op == BinaryOp::Or {
+                    let left = self.eval(left, scope.clone())?;
+                    if left.truthy() {
+                        return Ok(left);
+                    }
+                    return self.eval(right, scope);
+                }
+
+                let left = self.eval(left, scope.clone())?;
+                let right = self.eval(right, scope)?;
+                self.apply_binary(left, *op, right)
+            }
+            Expr::Call { callee, args } => {
+                if let Expr::Variable(name) = callee.as_ref() {
+                    if name == "print" {
+                        let values = args
+                            .iter()
+                            .map(|arg| self.eval(arg, scope.clone()))
+                            .collect::<RuntimeResult<Vec<_>>>()?;
+                        let rendered = values
+                            .iter()
+                            .map(Value::render)
+                            .collect::<Vec<_>>()
+                            .join(" ");
+                        self.output.push_str(&rendered);
+                        self.output.push('\n');
+                        return Ok(Value::None);
+                    }
+                }
+
+                let callee = self.eval(callee, scope.clone())?;
+                let args = args
+                    .iter()
+                    .map(|arg| self.eval(arg, scope.clone()))
+                    .collect::<RuntimeResult<Vec<_>>>()?;
+                self.call_function(callee, args)
+            }
+        }
+    }
+
+    fn apply_binary(&self, left: Value, op: BinaryOp, right: Value) -> RuntimeResult<Value> {
+        match op {
+            BinaryOp::Add => match (left, right) {
+                (Value::Int(left), Value::Int(right)) => Ok(Value::Int(left + right)),
+                (Value::String(left), Value::String(right)) => Ok(Value::String(left + &right)),
+                (left, right) => Err(RuntimeError(format!(
+                    "unsupported + between {} and {}",
+                    left.type_name(),
+                    right.type_name()
+                ))),
+            },
+            BinaryOp::Subtract => int_binop(left, right, |a, b| a - b, "-"),
+            BinaryOp::Multiply => int_binop(left, right, |a, b| a * b, "*"),
+            BinaryOp::Divide => {
+                let (left, right) = expect_ints(left, right, "/")?;
+                if right == 0 {
+                    return Err(RuntimeError("division by zero".to_string()));
+                }
+                Ok(Value::Int(left / right))
+            }
+            BinaryOp::Modulo => {
+                let (left, right) = expect_ints(left, right, "%")?;
+                if right == 0 {
+                    return Err(RuntimeError("modulo by zero".to_string()));
+                }
+                Ok(Value::Int(left % right))
+            }
+            BinaryOp::Equal => Ok(Value::Bool(left == right)),
+            BinaryOp::NotEqual => Ok(Value::Bool(left != right)),
+            BinaryOp::Less => compare_ints(left, right, |a, b| a < b, "<"),
+            BinaryOp::LessEqual => compare_ints(left, right, |a, b| a <= b, "<="),
+            BinaryOp::Greater => compare_ints(left, right, |a, b| a > b, ">"),
+            BinaryOp::GreaterEqual => compare_ints(left, right, |a, b| a >= b, ">="),
+            BinaryOp::And | BinaryOp::Or => unreachable!("short-circuit handled separately"),
+        }
+    }
+
+    fn call_function(&mut self, callee: Value, args: Vec<Value>) -> RuntimeResult<Value> {
+        match callee {
+            Value::Function(function) => {
+                if function.params.len() != args.len() {
+                    return Err(RuntimeError(format!(
+                        "{} expected {} args, got {}",
+                        function.name,
+                        function.params.len(),
+                        args.len()
+                    )));
+                }
+                let scope = Scope::child(function.closure.clone());
+                {
+                    let mut scope_mut = scope.borrow_mut();
+                    for (name, value) in function.params.iter().zip(args) {
+                        scope_mut.values.insert(name.clone(), value);
+                    }
+                }
+                Ok(self
+                    .execute_block(&function.body, scope)?
+                    .unwrap_or(Value::None))
+            }
+            other => Err(RuntimeError(format!(
+                "cannot call {}",
+                other.type_name()
+            ))),
+        }
+    }
+}
+
+fn int_binop(
+    left: Value,
+    right: Value,
+    op: impl FnOnce(i64, i64) -> i64,
+    symbol: &str,
+) -> RuntimeResult<Value> {
+    let (left, right) = expect_ints(left, right, symbol)?;
+    Ok(Value::Int(op(left, right)))
+}
+
+fn compare_ints(
+    left: Value,
+    right: Value,
+    cmp: impl FnOnce(i64, i64) -> bool,
+    symbol: &str,
+) -> RuntimeResult<Value> {
+    let (left, right) = expect_ints(left, right, symbol)?;
+    Ok(Value::Bool(cmp(left, right)))
+}
+
+fn expect_ints(left: Value, right: Value, symbol: &str) -> RuntimeResult<(i64, i64)> {
+    match (left, right) {
+        (Value::Int(left), Value::Int(right)) => Ok((left, right)),
+        (left, right) => Err(RuntimeError(format!(
+            "unsupported {symbol} between {} and {}",
+            left.type_name(),
+            right.type_name()
+        ))),
+    }
+}
+
+type ScopeRef = Rc<RefCell<Scope>>;
+
+#[derive(Debug, Default, Clone, PartialEq)]
+struct Scope {
+    values: HashMap<String, Value>,
+    parent: Option<ScopeRef>,
+}
+
+impl Scope {
+    fn child(parent: ScopeRef) -> ScopeRef {
+        Rc::new(RefCell::new(Self {
+            values: HashMap::new(),
+            parent: Some(parent),
+        }))
+    }
+
+    fn get(&self, name: &str) -> Option<Value> {
+        self.values
+            .get(name)
+            .cloned()
+            .or_else(|| self.parent.as_ref().and_then(|parent| parent.borrow().get(name)))
+    }
+}
+
+impl Default for Interpreter {
+    fn default() -> Self {
+        Self {
+            globals: Rc::new(RefCell::new(Scope::default())),
+            output: String::new(),
+        }
+    }
+}
+
+pub fn parse_program(source: &str) -> RuntimeResult<Vec<Stmt>> {
+    let lines = preprocess_lines(source)?;
+    let mut index = 0;
+    parse_block(&lines, &mut index, 0)
+}
+
+fn preprocess_lines(source: &str) -> RuntimeResult<Vec<Line>> {
+    let mut lines = Vec::new();
+    for (line_number, raw_line) in source.lines().enumerate() {
+        if raw_line.trim().is_empty() {
+            continue;
+        }
+        let indent = raw_line.chars().take_while(|ch| *ch == ' ').count();
+        if indent % 4 != 0 {
+            return Err(RuntimeError(format!(
+                "line {} has unsupported indentation",
+                line_number + 1
+            )));
+        }
+        let trimmed = raw_line.trim();
+        if trimmed.starts_with('#') {
+            continue;
+        }
+        lines.push(Line {
+            indent,
+            content: trimmed.to_string(),
+        });
+    }
+    Ok(lines)
+}
+
+fn parse_block(lines: &[Line], index: &mut usize, indent: usize) -> RuntimeResult<Vec<Stmt>> {
+    let mut statements = Vec::new();
+    while *index < lines.len() {
+        let line = &lines[*index];
+        if line.indent < indent {
+            break;
+        }
+        if line.indent > indent {
+            return Err(RuntimeError(format!(
+                "unexpected indentation near `{}`",
+                line.content
+            )));
+        }
