+
+    fn apply_binary(&self, left: Value, op: BinaryOp, right: Value) -> RuntimeResult<Value> {
+        match op {
+            BinaryOp::Add => match (left, right) {
+                (Value::Int(left), Value::Int(right)) => Ok(Value::Int(left + right)),
+                (Value::String(left), Value::String(right)) => Ok(Value::String(left + &right)),
+                (left, right) => Err(RuntimeError(format!(
+                    "unsupported + between {} and {}",
+                    left.type_name(),
+                    right.type_name()
+                ))),
+            },
+            BinaryOp::Subtract => int_binop(left, right, |a, b| a - b, "-"),
+            BinaryOp::Multiply => int_binop(left, right, |a, b| a * b, "*"),
+            BinaryOp::Divide => {
+                let (left, right) = expect_ints(left, right, "/")?;
+                if right == 0 {
+                    return Err(RuntimeError("division by zero".to_string()));
+                }
+                Ok(Value::Int(left / right))
+            }
+            BinaryOp::Modulo => {
+                let (left, right) = expect_ints(left, right, "%")?;
+                if right == 0 {
+                    return Err(RuntimeError("modulo by zero".to_string()));
+                }
+                Ok(Value::Int(left % right))
+            }
+            BinaryOp::Equal => Ok(Value::Bool(left == right)),
+            BinaryOp::NotEqual => Ok(Value::Bool(left != right)),
+            BinaryOp::Less => compare_ints(left, right, |a, b| a < b, "<"),
+            BinaryOp::LessEqual => compare_ints(left, right, |a, b| a <= b, "<="),
+            BinaryOp::Greater => compare_ints(left, right, |a, b| a > b, ">"),
+            BinaryOp::GreaterEqual => compare_ints(left, right, |a, b| a >= b, ">="),
