+
+    fn call_function(&mut self, callee: Value, args: Vec<Value>) -> RuntimeResult<Value> {
+        match callee {
+            Value::Function(function) => {
+                if function.params.len() != args.len() {
+                    return Err(RuntimeError(format!(
+                        "{} expected {} args, got {}",
+                        function.name,
+                        function.params.len(),
+                        args.len()
+                    )));
+                }
+                let scope = Scope::child(function.closure.clone());
+                {
+                    let mut scope_mut = scope.borrow_mut();
+                    for (name, value) in function.params.iter().zip(args) {
+                        scope_mut.values.insert(name.clone(), value);
+                    }
+                }
+                Ok(self
+                    .execute_block(&function.body, scope)?
+                    .unwrap_or(Value::None))
+            }
+            other => Err(RuntimeError(format!(
+                "cannot call {}",
+                other.type_name()
+            ))),
+        }
+    }
+}
+
+fn int_binop(
+    left: Value,
+    right: Value,
+    op: impl FnOnce(i64, i64) -> i64,
+    symbol: &str,
+) -> RuntimeResult<Value> {
+    let (left, right) = expect_ints(left, right, symbol)?;
+    Ok(Value::Int(op(left, right)))
+}
+
+fn compare_ints(
+    left: Value,
+    right: Value,
+    cmp: impl FnOnce(i64, i64) -> bool,
+    symbol: &str,
+) -> RuntimeResult<Value> {
+    let (left, right) = expect_ints(left, right, symbol)?;
+    Ok(Value::Bool(cmp(left, right)))
+}
+
+fn expect_ints(left: Value, right: Value, symbol: &str) -> RuntimeResult<(i64, i64)> {
+    match (left, right) {
+        (Value::Int(left), Value::Int(right)) => Ok((left, right)),
+        (left, right) => Err(RuntimeError(format!(
+            "unsupported {symbol} between {} and {}",
+            left.type_name(),
+            right.type_name()
+        ))),
+    }
+}
+
+type ScopeRef = Rc<RefCell<Scope>>;
+
+#[derive(Debug, Default, Clone, PartialEq)]
+struct Scope {
+    values: HashMap<String, Value>,
+    parent: Option<ScopeRef>,
+}
+
+impl Scope {
+    fn child(parent: ScopeRef) -> ScopeRef {
+        Rc::new(RefCell::new(Self {
+            values: HashMap::new(),
+            parent: Some(parent),
+        }))
+    }
+
+    fn get(&self, name: &str) -> Option<Value> {
+        self.values
+            .get(name)
+            .cloned()
+            .or_else(|| self.parent.as_ref().and_then(|parent| parent.borrow().get(name)))
+    }
+}
+
+impl Default for Interpreter {
+    fn default() -> Self {
+        Self {
+            globals: Rc::new(RefCell::new(Scope::default())),
+            output: String::new(),
+        }
+    }
+}
+
+pub fn parse_program(source: &str) -> RuntimeResult<Vec<Stmt>> {
+    let lines = preprocess_lines(source)?;
+    let mut index = 0;
+    parse_block(&lines, &mut index, 0)
+}
+
+fn preprocess_lines(source: &str) -> RuntimeResult<Vec<Line>> {
+    let mut lines = Vec::new();
+    for (line_number, raw_line) in source.lines().enumerate() {
+        if raw_line.trim().is_empty() {
+            continue;
+        }
+        let indent = raw_line.chars().take_while(|ch| *ch == ' ').count();
+        if indent % 4 != 0 {
+            return Err(RuntimeError(format!(
+                "line {} has unsupported indentation",
+                line_number + 1
+            )));
+        }
+        let trimmed = raw_line.trim();
+        if trimmed.starts_with('#') {
+            continue;
+        }
+        lines.push(Line {
+            indent,
+            content: trimmed.to_string(),
+        });
+    }
+    Ok(lines)
+}
+
+fn parse_block(lines: &[Line], index: &mut usize, indent: usize) -> RuntimeResult<Vec<Stmt>> {
+    let mut statements = Vec::new();
+    while *index < lines.len() {
+        let line = &lines[*index];
+        if line.indent < indent {
+            break;
+        }
+        if line.indent > indent {
+            return Err(RuntimeError(format!(
+                "unexpected indentation near `{}`",
+                line.content
+            )));
+        }
+
+        if let Some(rest) = line.content.strip_prefix("def ") {
+            let (name, params) = parse_signature(rest)?;
+            *index += 1;
+            let body = parse_required_nested_block(lines, index, indent, "function")?;
+            statements.push(Stmt::FunctionDef { name, params, body });
+            continue;
+        }
+
+        if let Some(condition_src) = line.content.strip_prefix("if ") {
+            let condition = parse_colon_expr(condition_src)?;
+            *index += 1;
+            let then_body = parse_required_nested_block(lines, index, indent, "if")?;
+            let mut else_body = Vec::new();
+            if *index < lines.len()
+                && lines[*index].indent == indent
+                && lines[*index].content == "else:"
+            {
+                *index += 1;
+                else_body = parse_required_nested_block(lines, index, indent, "else")?;
+            }
+            statements.push(Stmt::If {
+                condition,
+                then_body,
+                else_body,
+            });
+            continue;
+        }
+
+        if let Some(condition_src) = line.content.strip_prefix("while ") {
+            let condition = parse_colon_expr(condition_src)?;
+            *index += 1;
+            let body = parse_required_nested_block(lines, index, indent, "while")?;
+            statements.push(Stmt::While { condition, body });
+            continue;
+        }
+
+        if let Some(expr_src) = line.content.strip_prefix("return ") {
+            statements.push(Stmt::Return(parse_expr(expr_src)?));
+            *index += 1;
+            continue;
+        }
+
+        if line.content == "return" {
+            statements.push(Stmt::Return(Expr::Value(Value::None)));
+            *index += 1;
+            continue;
+        }
+
+        if line.content == "else:" {
+            break;
+        }
+
+        if let Some((name, expr_src)) = split_assignment(&line.content) {
+            statements.push(Stmt::Assign {
+                name,
+                expr: parse_expr(&expr_src)?,
+            });
+        } else {
+            statements.push(Stmt::Expr(parse_expr(&line.content)?));
+        }
+        *index += 1;
+    }
+    Ok(statements)
+}
+
+fn parse_required_nested_block(
+    lines: &[Line],
+    index: &mut usize,
+    parent_indent: usize,
+    label: &str,
+) -> RuntimeResult<Vec<Stmt>> {
+    let next = lines
+        .get(*index)
+        .ok_or_else(|| RuntimeError(format!("{label} block is missing a body")))?;
+    if next.indent <= parent_indent {
+        return Err(RuntimeError(format!("{label} block is missing an indented body")));
+    }
+    parse_block(lines, index, next.indent)
+}
+
+fn parse_signature(rest: &str) -> RuntimeResult<(String, Vec<String>)> {
+    let rest = rest
+        .strip_suffix(':')
+        .ok_or_else(|| RuntimeError("function definition must end with ':'".to_string()))?;
+    let open = rest
+        .find('(')
+        .ok_or_else(|| RuntimeError("function definition is missing '('".to_string()))?;
+    let close = rest
+        .rfind(')')
+        .ok_or_else(|| RuntimeError("function definition is missing ')'".to_string()))?;
+    if close < open {
+        return Err(RuntimeError("malformed function signature".to_string()));
+    }
+    let name = rest[..open].trim();
+    if name.is_empty() {
+        return Err(RuntimeError("function name is required".to_string()));
+    }
+    let params_src = &rest[open + 1..close];
+    let params = if params_src.trim().is_empty() {
+        Vec::new()
+    } else {
+        params_src
+            .split(',')
+            .map(|part| {
+                let name = part.trim();
+                if is_identifier(name) {
+                    Ok(name.to_string())
+                } else {
+                    Err(RuntimeError(format!("invalid parameter name: {name}")))
+                }
+            })
+            .collect::<RuntimeResult<Vec<_>>>()?
+    };
+    Ok((name.to_string(), params))
+}
+
+fn parse_colon_expr(source: &str) -> RuntimeResult<Expr> {
+    let expr = source
+        .strip_suffix(':')
+        .ok_or_else(|| RuntimeError("expected ':'".to_string()))?;
+    parse_expr(expr)
+}
+
+fn split_assignment(line: &str) -> Option<(String, String)> {
+    let mut depth = 0usize;
+    let chars: Vec<(usize, char)> = line.char_indices().collect();
+    let mut in_string = false;
+    let mut string_quote = '\0';
+
+    for (index, ch) in chars {
+        if in_string {
+            if ch == string_quote {
+                in_string = false;
+            }
+            continue;
+        }
+        match ch {
+            '"' | '\'' => {
+                in_string = true;
+                string_quote = ch;
+            }
+            '(' => depth += 1,
+            ')' => depth = depth.saturating_sub(1),
+            '=' if depth == 0 => {
+                let next = line[index + 1..].chars().next();
+                let prev = line[..index].chars().last();
+                if matches!(next, Some('=')) || matches!(prev, Some('!' | '<' | '>')) {
+                    continue;
+                }
+                let name = line[..index].trim();
+                if is_identifier(name) {
+                    return Some((name.to_string(), line[index + 1..].trim().to_string()));
+                }
+            }
+            _ => {}
+        }
+    }
+    None
+}
+
+fn is_identifier(name: &str) -> bool {
+    let mut chars = name.chars();
+    match chars.next() {
+        Some(ch) if ch == '_' || ch.is_ascii_alphabetic() => {}
+        _ => return false,
+    }
+    chars.all(|ch| ch == '_' || ch.is_ascii_alphanumeric())
+}
+
+fn parse_expr(source: &str) -> RuntimeResult<Expr> {
+    let tokens = tokenize(source)?;
+    let mut parser = ExprParser::new(tokens);
+    let expr = parser.parse_expression(0)?;
+    if parser.peek() != &Token::Eof {
+        return Err(RuntimeError("unexpected token at end of expression".to_string()));
+    }
+    Ok(expr)
+}
+
+fn tokenize(source: &str) -> RuntimeResult<Vec<Token>> {
+    let mut chars = source.chars().peekable();
+    let mut tokens = Vec::new();
+
+    while let Some(ch) = chars.peek().copied() {
+        match ch {
+            ' ' | '\t' => {
+                chars.next();
+            }
+            '0'..='9' => {
+                let mut value = String::new();
+                while let Some(next) = chars.peek().copied() {
+                    if next.is_ascii_digit() {
+                        value.push(next);
+                        chars.next();
+                    } else {
+                        break;
+                    }
+                }
+                let value = value
+                    .parse::<i64>()
+                    .map_err(|_| RuntimeError("invalid integer literal".to_string()))?;
+                tokens.push(Token::Int(value));
+            }
+            '"' | '\'' => {
+                let quote = chars.next().unwrap_or('"');
+                let mut value = String::new();
+                loop {
+                    match chars.next() {
+                        Some(next) if next == quote => break,
+                        Some('\\') => match chars.next() {
+                            Some('n') => value.push('\n'),
+                            Some('t') => value.push('\t'),
+                            Some('"') => value.push('"'),
+                            Some('\'') => value.push('\''),
+                            Some('\\') => value.push('\\'),
+                            Some(other) => {
+                                return Err(RuntimeError(format!(
+                                    "unsupported escape sequence: \\{other}"
+                                )))
+                            }
+                            None => {
+                                return Err(RuntimeError(
+                                    "unterminated escape sequence".to_string(),
+                                ))
+                            }
+                        },
+                        Some(next) => value.push(next),
+                        None => return Err(RuntimeError("unterminated string literal".to_string())),
+                    }
+                }
+                tokens.push(Token::String(value));
+            }
+            '(' => {
+                chars.next();
+                tokens.push(Token::LParen);
+            }
+            ')' => {
+                chars.next();
+                tokens.push(Token::RParen);
+            }
+            ',' => {
+                chars.next();
+                tokens.push(Token::Comma);
+            }
+            '+' => {
+                chars.next();
+                tokens.push(Token::Plus);
+            }
+            '-' => {
+                chars.next();
+                tokens.push(Token::Minus);
+            }
+            '*' => {
+                chars.next();
+                tokens.push(Token::Star);
+            }
+            '/' => {
+                chars.next();
+                tokens.push(Token::Slash);
+            }
+            '%' => {
+                chars.next();
+                tokens.push(Token::Percent);
+            }
+            '=' => {
+                chars.next();
+                if chars.next_if_eq(&'=').is_some() {
+                    tokens.push(Token::EqEq);
+                } else {
+                    return Err(RuntimeError("unexpected '=' in expression".to_string()));
+                }
+            }
+            '!' => {
+                chars.next();
+                if chars.next_if_eq(&'=').is_some() {
+                    tokens.push(Token::NotEq);
+                } else {
+                    return Err(RuntimeError("expected '!='".to_string()));
+                }
+            }
+            '<' => {
+                chars.next();
+                if chars.next_if_eq(&'=').is_some() {
+                    tokens.push(Token::LtEq);
+                } else {
+                    tokens.push(Token::Lt);
+                }
+            }
+            '>' => {
+                chars.next();
+                if chars.next_if_eq(&'=').is_some() {
+                    tokens.push(Token::GtEq);
+                } else {
+                    tokens.push(Token::Gt);
+                }
+            }
+            '_' | 'a'..='z' | 'A'..='Z' => {
+                let mut ident = String::new();
+                while let Some(next) = chars.peek().copied() {
+                    if next == '_' || next.is_ascii_alphanumeric() {
+                        ident.push(next);
+                        chars.next();
+                    } else {
+                        break;
+                    }
+                }
+                tokens.push(match ident.as_str() {
+                    "True" => Token::True,
+                    "False" => Token::False,
+                    "None" => Token::None,
+                    "and" => Token::And,
+                    "or" => Token::Or,
+                    "not" => Token::Not,
+                    _ => Token::Identifier(ident),
+                });
+            }
+            _ => return Err(RuntimeError(format!("unexpected character: {ch}"))),
+        }
+    }
+
+    tokens.push(Token::Eof);
+    Ok(tokens)
+}
+
+struct ExprParser {
+    tokens: Vec<Token>,
+    cursor: usize,
+}
+
+impl ExprParser {
+    fn new(tokens: Vec<Token>) -> Self {
+        Self { tokens, cursor: 0 }
+    }
+
+    fn peek(&self) -> &Token {
+        self.tokens.get(self.cursor).unwrap_or(&Token::Eof)
+    }
+
+    fn advance(&mut self) -> Token {
+        let token = self.tokens.get(self.cursor).cloned().unwrap_or(Token::Eof);
+        self.cursor += 1;
+        token
+    }
+
+    fn parse_expression(&mut self, min_precedence: u8) -> RuntimeResult<Expr> {
+        let mut left = self.parse_prefix()?;
+
+        loop {
+            if let Token::LParen = self.peek() {
+                left = self.parse_call(left)?;
+                continue;
+            }
+
+            let Some((op, precedence)) = infix_binding(self.peek()) else {
+                break;
+            };
+            if precedence < min_precedence {
+                break;
+            }
+            self.advance();
+            let right = self.parse_expression(precedence + 1)?;
+            left = Expr::Binary {
+                left: Box::new(left),
+                op,
+                right: Box::new(right),
+            };
+        }
+
+        Ok(left)
+    }
+
+    fn parse_prefix(&mut self) -> RuntimeResult<Expr> {
+        match self.advance() {
+            Token::Int(value) => Ok(Expr::Value(Value::Int(value))),
+            Token::String(value) => Ok(Expr::Value(Value::String(value))),
+            Token::True => Ok(Expr::Value(Value::Bool(true))),
+            Token::False => Ok(Expr::Value(Value::Bool(false))),
+            Token::None => Ok(Expr::Value(Value::None)),
+            Token::Identifier(name) => Ok(Expr::Variable(name)),
+            Token::Minus => Ok(Expr::Unary {
+                op: UnaryOp::Negate,
+                expr: Box::new(self.parse_expression(7)?),
+            }),
+            Token::Not => Ok(Expr::Unary {
+                op: UnaryOp::Not,
+                expr: Box::new(self.parse_expression(7)?),
+            }),
+            Token::LParen => {
+                let expr = self.parse_expression(0)?;
+                match self.advance() {
+                    Token::RParen => Ok(expr),
+                    _ => Err(RuntimeError("expected ')'".to_string())),
+                }
+            }
+            token => Err(RuntimeError(format!("unexpected token: {:?}", token))),
+        }
+    }
+
+    fn parse_call(&mut self, callee: Expr) -> RuntimeResult<Expr> {
+        self.expect(Token::LParen)?;
+        let mut args = Vec::new();
+        if self.peek() != &Token::RParen {
+            loop {
+                args.push(self.parse_expression(0)?);
+                if self.peek() == &Token::Comma {
+                    self.advance();
+                    continue;
+                }
+                break;
+            }
+        }
+        self.expect(Token::RParen)?;
+        Ok(Expr::Call {
+            callee: Box::new(callee),
+            args,
+        })
+    }
+
+    fn expect(&mut self, expected: Token) -> RuntimeResult<()> {
+        let token = self.advance();
+        if token == expected {
+            Ok(())
+        } else {
+            Err(RuntimeError(format!(
+                "expected {:?}, found {:?}",
+                expected, token
+            )))
+        }
+    }
+}
+
+fn infix_binding(token: &Token) -> Option<(BinaryOp, u8)> {
+    match token {
+        Token::Or => Some((BinaryOp::Or, 1)),
+        Token::And => Some((BinaryOp::And, 2)),
+        Token::EqEq => Some((BinaryOp::Equal, 3)),
+        Token::NotEq => Some((BinaryOp::NotEqual, 3)),
+        Token::Lt => Some((BinaryOp::Less, 4)),
+        Token::LtEq => Some((BinaryOp::LessEqual, 4)),
+        Token::Gt => Some((BinaryOp::Greater, 4)),
+        Token::GtEq => Some((BinaryOp::GreaterEqual, 4)),
+        Token::Plus => Some((BinaryOp::Add, 5)),
+        Token::Minus => Some((BinaryOp::Subtract, 5)),
+        Token::Star => Some((BinaryOp::Multiply, 6)),
+        Token::Slash => Some((BinaryOp::Divide, 6)),
+        Token::Percent => Some((BinaryOp::Modulo, 6)),
+        _ => None,
+    }
+}
+
