    #[test]
    fn executes_arithmetic_and_looping() {
        let source = r#"
count = 0
total = 0

while count < 5:
    total = total + count
    count = count + 1

print(total)
"#;

        let mut interpreter = Interpreter::new();
        let output = interpreter.run(source).expect("program should run");
        assert_eq!(output, "10\n");
    }

    #[test]
    fn supports_functions_and_conditionals() {
        let source = r#"
def classify(value):
    if value > 10:
        return "large"
    else:
        return "small"

print(classify(3))
print(classify(17))
"#;

        let mut interpreter = Interpreter::new();
        let output = interpreter.run(source).expect("program should run");
        assert_eq!(output, "small\nlarge\n");
    }
}

