314	    fn apply_binary(&self, left: Value, op: BinaryOp, right: Value) -> RuntimeResult<Value> {
315	        match op {
316	            BinaryOp::Add => match (left, right) {
317	                (Value::Int(left), Value::Int(right)) => Ok(Value::Int(left + right)),
318	                (Value::String(left), Value::String(right)) => Ok(Value::String(left + &right)),
319	                (left, right) => Err(RuntimeError(format!(
320	                    "unsupported + between {} and {}",
321	                    left.type_name(),
322	                    right.type_name()
323	                ))),
324	            },
325	            BinaryOp::Subtract => int_binop(left, right, |a, b| a - b, "-"),
326	            BinaryOp::Multiply => int_binop(left, right, |a, b| a * b, "*"),
327	            BinaryOp::Divide => {
328	                let (left, right) = expect_ints(left, right, "/")?;
329	                if right == 0 {
330	                    return Err(RuntimeError("division by zero".to_string()));
331	                }
332	                Ok(Value::Int(left / right))
333	            }
334	            BinaryOp::Modulo => {
335	                let (left, right) = expect_ints(left, right, "%")?;
336	                if right == 0 {
337	                    return Err(RuntimeError("modulo by zero".to_string()));
338	                }
339	                Ok(Value::Int(left % right))
340	            }
341	            BinaryOp::Equal => Ok(Value::Bool(left == right)),
342	            BinaryOp::NotEqual => Ok(Value::Bool(left != right)),
343	            BinaryOp::Less => compare_ints(left, right, |a, b| a < b, "<"),
344	            BinaryOp::LessEqual => compare_ints(left, right, |a, b| a <= b, "<="),
345	            BinaryOp::Greater => compare_ints(left, right, |a, b| a > b, ">"),
346	            BinaryOp::GreaterEqual => compare_ints(left, right, |a, b| a >= b, ">="),
347	            BinaryOp::And | BinaryOp::Or => unreachable!("short-circuit handled separately"),
348	        }
349	    }
