352	        match callee {
353	            Value::Function(function) => {
354	                if function.params.len() != args.len() {
355	                    return Err(RuntimeError(format!(
356	    …4965 chars truncated…      }
497	        if line.indent > indent {
498	            return Err(RuntimeError(format!(
499	                "unexpected indentation near `{}`",
500	                line.content
501	            )));
502	        }
503	
504	        if let Some(rest) = line.content.strip_prefix("def ") {
505	            let (name, params) = parse_signature(rest)?;
506	            *index += 1;
507	            let body = parse_required_nested_block(lines, index, indent, "function")?;
508	            statements.push(Stmt::FunctionDef { name, params, body });
509	            continue;
510	        }
511	
512	        if let Some(condition_src) = line.content.strip_prefix("if ") {
513	            let condition = parse_colon_expr(condition_src)?;
514	            *index += 1;
515	            let then_body = parse_required_nested_block(lines, index, indent, "if")?;
516	            let mut else_body = Vec::new();
517	            if *index < lines.len()
518	                && lines[*index].indent == indent
519	                && lines[*index].content == "else:"
520	            {
521	                *index += 1;
522	                else_body = parse_required_nested_block(lines, index, indent, "else")?;
523	            }
524	            statements.push(Stmt::If {
525	                condition,
526	                then_body,
527	                else_body,
528	            });
529	            continue;
530	        }
531	
532	        if let Some(condition_src) = line.content.strip_prefix("while ") {
533	            let condition = parse_colon_expr(condition_src)?;
534	            *index += 1;
535	            let body = parse_required_nested_block(lines, index, indent, "while")?;
536	            statements.push(Stmt::While { condition, body });
537	            continue;
538	        }
539	
540	        if let Some(expr_src) = line.content.strip_prefix("return ") {
541	            statements.push(Stmt::Return(parse_expr(expr_src)?));
542	            *index += 1;
543	            continue;
544	        }
545	
546	        if line.content == "return" {
547	            statements.push(Stmt::Return(Expr::Value(Value::None)));
548	            *index += 1;
549	            continue;
550	        }
551	
552	        if line.content == "else:" {
553	            break;
554	        }
555	
556	        if let Some((name, expr_src)) = split_assignment(&line.content) {
557	            statements.push(Stmt::Assign {
558	                name,
559	                expr: parse_expr(&expr_src)?,
560	            });
561	        } else {
562	            statements.push(Stmt::Expr(parse_expr(&line.content)?));
563	        }
564	        *index += 1;
565	    }
566	    Ok(statements)
567	}
