569	fn parse_required_nested_block(
570	    lines: &[Line],
571	    index: &mut usize,
572	    parent_indent: usize,
573	    label: &str,
574	) -> RuntimeResult<Vec<Stmt>> {
575	    let next = lines
576	        .get(*index)
577	        .ok_or_else(|| RuntimeError(format!("{label} block is missing a body")))?;
578	    if next.indent <= parent_indent {
579	        return Err(RuntimeError(format!(
580	            "{label} block is missing an indented body"
581	        )));
582	    }
583	    parse_block(lines, index, next.indent)
584	}
