586	fn parse_signature(rest: &str) -> RuntimeResult<(String, Vec<String>)> {
587	    let rest = rest
588	        .strip_suffix(':')
589	        .ok_or_else(|| RuntimeError("function definition must end with ':'".to_string()))?;
590	    let open = rest
591	        .find('(')
592	        .ok_or_else(|| RuntimeError("function definition is missing '('".to_string()))?;
593	    let close = rest
594	        .rfind(')')
595	        .ok_or_else(|| RuntimeError("function definition is missing ')'".to_string()))?;
596	    if close < open {
597	        return Err(RuntimeError("malformed function signature".to_string()));
598	    }
599	    let name = rest[..open].trim();
600	    if name.is_empty() {
601	        return Err(RuntimeError("function name is required".to_string()));
602	    }
603	    let params_src = &rest[open + 1..close];
604	    let params = if params_src.trim().is_empty() {
605	        Vec::new()
606	    } else {
607	        params_src
608	            .split(',')
609	            .map(|part| {
610	                let name = part.trim();
611	                if is_identifier(name) {
612	                    Ok(name.to_string())
613	                } else {
614	                    Err(RuntimeError(format!("invalid parameter name: {name}")))
615	                }
616	            })
617	            .collect::<RuntimeResult<Vec<_>>>()?
618	    };
619	    Ok((name.to_string(), params))
620	}
